import{e as r,ab as t,a1 as i,m as o,r as n,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [May]","description":"May 2023 updates.","frontmatter":{"title":"Monthly Updates [May]","description":"May 2023 updates.","date":"2023-05-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/may-2023.md","filePath":"posts/may-2023.md"}'),d={name:"posts/may-2023.md"};function l(p,e,m,h,f,g){const a=t("Post");return i(),o("div",null,[n(a,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Added <strong><a href="https://rentry.org/The-Piracy-Glossary" target="_blank" rel="noreferrer">The Piracy Glossary ☠️</a></strong>, where we&#39;ve organized and provided explanations for every piracy-related term we could think of.</p></li><li><p>Added Optimization, Tweaking, Virtual Machines, and Terminal / CLI subsections to <a href="/system-tools">System Tools</a>.</p></li><li><p>Added Chat / Forums, Image / Video, Interactive, Interesting, and Random subsections to <a href="/misc/#fun-sites">Fun Sites</a>.</p></li><li><p>Added a <a href="/misc/#gardening">Gardening</a> section to Miscellaneous.</p></li><li><p>Created a <a href="/downloading/#software-sites">Software CSE</a> out of the Software sites.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="/gaming/#download-games">Torrminatorr</a> in Gaming Sites. Torrminatorr is back!</p></li><li><p>Starred <a href="/gaming/#download-games">GOG Games</a> in Gaming Sites. GOG is back on the Clearnet!</p></li><li><p>Starred <a href="/downloading/#software-sites">FileCR</a> in Software Sites. FileCR has removed their anti-adblock.</p></li><li><p>Starred <a href="/video/#dedicated-hosts">Streaminal-TV</a> in Streaming Sites. Nice UI, fast 1080p.</p></li><li><p>Starred <a href="/video/#anime-downloading">TokyoInsider</a> in Anime Downloading. Anime site with single-click DDLs.</p></li><li><p>Starred <a href="/reading/#manga-sites">Cubari</a> in Manga Sites. Multi-site manga scraper.</p></li><li><p>Starred <a href="https://addons.mozilla.org/en-US/firefox/addon/foxytab/" target="_blank" rel="noreferrer">FoxyTab</a>, <a href="https://addons.mozilla.org/en-US/firefox/addon/zoom-page-we/" target="_blank" rel="noreferrer">Zoom Page WE</a>, and <a href="https://addons.mozilla.org/en-US/firefox/addon/scroll_anywhere/" target="_blank" rel="noreferrer">Scroll Anywhere</a> in Browser Extensions.</p></li><li><p>Starred <a href="/misc/#random">PokeSmash</a> in Fun Sites.</p></li><li><p>Re-added + starred <a href="/video/#cartoon-streaming">WCO</a> in Cartoon Streaming. This went paid for a bit but seems to be free again.</p></li><li><p>Re-added + starred <a href="/mobile/#android-streaming">CloudStream</a> in Android Streaming. Some extensions are still getting updates.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Unstarred WebOasis in Indexes. Doesn&#39;t seem to be getting updated anymore. RIP Webby.</p></li><li><p>Unstarred UniqueStream, HDMovieBox, and Pirate-Media in Streaming for being slow or dead.</p></li><li><p>Unstarred Soft98 in Software as most downloads are dead.</p></li><li><p>Removed Midjourney in Image Gen as it&#39;s <a href="https://youtu.be/EHnUydrurmk" target="_blank" rel="noreferrer">no longer free</a>.</p></li></ul>',9))])}const S=r(d,[["render",l]]);export{u as __pageData,S as default};
